export function icon(name){if(!Object.hasOwn(paths,name))throw new Error('Unknown icon: '+name);return '<svg class="works-icon" width="20" height="20" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" focusable="false">'+paths[name]+'</svg>';}
export function hydrateIcons(root=document){for(const el of root.querySelectorAll('[data-works-icon]')){const template=document.createElement('template');template.innerHTML=icon(el.dataset.worksIcon);const svg=template.content.firstElementChild;for(const attr of el.attributes){if(attr.name!=='data-works-icon'&&attr.name!=='aria-hidden')svg.setAttribute(attr.name,attr.value);}el.replaceWith(svg);}}
